function useLocale() {
  const { i18n } = useTranslation();
  return i18n.language === "pt-BR" ? "pt-BR" : "en-US";
}

function useSelectedOrganization() {
  const { user } = useAuth();
  const selectedId = useOrganizationStore((state) => state.selectedOrganizationId);
  const id = user?.organizations.some((organization) => organization.id === selectedId) ? selectedId : user?.organizations[0]?.id ?? null;
  return id;
}

function LoadingState({ label = "Loading" }: { label?: string }) {
  return <div className="empty-state" role="status"><span className="empty-state__icon"><Sparkles size={22} /></span><h3>{label}</h3></div>;
}

function ErrorState({ message, onRetry }: { message: string; onRetry: () => void }) {
  return <EmptyState icon={RotateCcw} title="Something needs attention" description={message} action={<Button variant="secondary" onClick={onRetry}>Try again</Button>} />;
}

function ProtectedRoute({ children }: { children: ReactNode }) {
  const auth = useAuth();
  const location = useLocation();
  if (auth.status === "initializing") return <LoadingState label="Restoring your session" />;
  if (auth.status !== "authenticated") {
    const returnTo = `${location.pathname}${location.search}`;
    return <Navigate to={`/auth/sign-in?returnTo=${encodeURIComponent(returnTo)}`} replace />;
  }
  if (!auth.user?.organizations.length && location.pathname !== "/account/create-organization") return <Navigate to="/account/create-organization" replace />;
  return <>{children}</>;
}

export function App() {
  return <Routes>
    <Route path="/" element={<HomePage />} />
    <Route path="/auth/sign-in" element={<AuthPage mode="sign-in" />} />
    <Route path="/auth/sign-up" element={<AuthPage mode="sign-up" />} />
    <Route path="/join-organization" element={<JoinPage />} />
    <Route path="/account/create-organization" element={<CreateOrganizationPage />} />
    <Route element={<ProtectedRoute><AppShell /></ProtectedRoute>}>
      <Route path="/dashboard" element={<DashboardPage />} />
      <Route path="/dashboard/bills" element={<BillsPage />} />
      <Route path="/dashboard/bills/:billId" element={<BillDetailsPage />} />
      <Route path="/dashboard/expenses" element={<ExpensesPage />} />
      <Route path="/dashboard/expenses/:expenseId" element={<ExpenseDetailsPage />} />
      <Route path="/account/settings" element={<AccountPage />} />
      <Route path="/account/organization" element={<OrganizationPage />} />
      <Route path="/organization/members" element={<MembersPage />} />
      <Route path="/account/more" element={<MorePage />} />
    </Route>
    <Route path="*" element={<NotFoundPage />} />
  </Routes>;
}

